CREATE TABLE `DyePotionInfo` (
  `ItemType` tinyint unsigned NOT NULL DEFAULT '0',
  `Name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `EName` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `Price` int unsigned NOT NULL DEFAULT '0',
  `Volume` tinyint unsigned NOT NULL DEFAULT '0',
  `Weight` tinyint unsigned NOT NULL DEFAULT '0',
  `Ratio` int NOT NULL DEFAULT '0',
  `ItemLevel` tinyint unsigned NOT NULL DEFAULT '0',
  `FunctionFlag` tinyint unsigned NOT NULL DEFAULT '0',
  `FunctionValue` smallint NOT NULL DEFAULT '0',
  `Race` tinyint unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`ItemType`) USING BTREE
