DROP TABLE IF EXISTS `OptionInfo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `OptionInfo` (
  `OptionType` int NOT NULL DEFAULT '0',
  `Nickname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `Name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `HName` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `Class` int NOT NULL DEFAULT '0',
  `PlusPoint` int NOT NULL DEFAULT '0',
  `PriceMultiplier` int NOT NULL DEFAULT '0',
  `ReqAbility` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `Color` int NOT NULL DEFAULT '0',
  `Ratio` int NOT NULL DEFAULT '0',
  `OptionLevel` int NOT NULL DEFAULT '0',
  `GambleLevel` int NOT NULL DEFAULT '0',
  `UpgradeOptionType` int NOT NULL DEFAULT '0',
  `UpgradeOptionType2` int NOT NULL DEFAULT '0',
  `UpgradeOptionType3` int NOT NULL DEFAULT '0',
  `UpgradeRatio` int NOT NULL DEFAULT '0',
  `UpgradeRatio2` int NOT NULL DEFAULT '0',
  `Notice` int NOT NULL DEFAULT '0',
  `UpgradeRatio3` int NOT NULL DEFAULT '0',
  `UpgradeSecondRatio` int NOT NULL DEFAULT '0',
  `UpgradeCrashPercent` tinyint NOT NULL DEFAULT '0',
  `PreviousOptionType` tinyint unsigned NOT NULL DEFAULT '0',
  `NextOptionRatio` tinyint NOT NULL DEFAULT '0',
  `Grade` int NOT NULL DEFAULT '0',
  `BlueBirdRatio` int NOT NULL DEFAULT '0',
  `rallser` int NOT NULL DEFAULT '0',
  `Count` int NOT NULL,
  PRIMARY KEY (`OptionType`) USING BTREE
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

