  `ItemFlag` tinyint NOT NULL DEFAULT '0',
  `Grade` smallint unsigned NOT NULL DEFAULT '6',
  `GTwoOptionType` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
