  `PlayerID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `MatchCount` int NOT NULL DEFAULT '1',
  `BanSeconds` int NOT NULL DEFAULT '0',
  `RawLine` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `CreatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `BannedAt` datetime DEFAULT NULL,
  `UnbannedAt` datetime DEFAULT NULL,
