CREATE TABLE `TrouserInfo` (
  `ItemType` tinyint unsigned NOT NULL DEFAULT '0',
  `NextItemType` tinyint unsigned NOT NULL DEFAULT '0',
  `Name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
