  `Price` int unsigned NOT NULL DEFAULT '0',
  `Volume` tinyint unsigned NOT NULL DEFAULT '0',
  `Weight` tinyint unsigned NOT NULL DEFAULT '0',
  `Ratio` int NOT NULL DEFAULT '0',
  `Durability` smallint unsigned NOT NULL DEFAULT '0',
  `Defense` tinyint unsigned NOT NULL DEFAULT '0',
  `Protection` tinyint unsigned NOT NULL DEFAULT '0',
  `ReqAbility` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `ItemLevel` tinyint unsigned NOT NULL DEFAULT '0',
  `DefaultOption` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `UpgradeCrashPercent` tinyint NOT NULL DEFAULT '0',
  `UpgradeRatio` smallint NOT NULL DEFAULT '0',
  `NextOptionRatio` tinyint unsigned NOT NULL DEFAULT '0',
  `DowngradeRatio` smallint NOT NULL DEFAULT '0',
  `Race` tinyint unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`ItemType`) USING BTREE
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
