DROP TABLE IF EXISTS `TrouserObject`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `TrouserObject` (
  `ItemID` bigint NOT NULL AUTO_INCREMENT,
  `World` enum('MOLD','WALA','HIST','BRAS') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'BRAS',
  `OldItemID` bigint unsigned DEFAULT NULL,
  `ObjectID` int unsigned NOT NULL DEFAULT '0',
  `ItemType` tinyint unsigned NOT NULL DEFAULT '0',
  `OwnerID` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `Storage` tinyint unsigned NOT NULL DEFAULT '0',
  `StorageID` bigint unsigned NOT NULL DEFAULT '0',
  `X` tinyint unsigned NOT NULL DEFAULT '0',
  `Y` tinyint unsigned NOT NULL DEFAULT '0',
  `OptionType` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `ThirdOptionType` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `Durability` smallint unsigned NOT NULL DEFAULT '0',
  `EnchantLevel` smallint unsigned NOT NULL DEFAULT '0',
  `ItemFlag` tinyint NOT NULL DEFAULT '0',
  `Grade` smallint unsigned NOT NULL DEFAULT '6',
